func (db *DB) FileSize() (int64, error) {
	var size int64
	files, err := db.opts.FileSystem.ReadDir(".")
	if err != nil {
		return 0, errors.Wrap(err, "reading directory")
	}
	for _, file := range files {
		info, err := file.Info()
